A Flask login flow can use Flask-Login, Werkzeug password hashing, and Redis-based lockout protection.

### 1. Install dependencies

```bash
pip install Flask==2.3.1 Flask-Login==0.6.2 redis
```

### 2. Configure Flask-Login

```python
# app.py
import logging
import os

from flask import Flask
from flask_login import LoginManager

from auth import auth_bp


def create_app():
    app = Flask(__name__)
    app.config["SECRET_KEY"] = os.environ["SECRET_KEY"]

    logging.basicConfig(
        filename="budget_tracker.log",
        level=logging.DEBUG,
        format="%(asctime)s %(levelname)s %(message)s",
    )

    login_manager = LoginManager(app)
    login_manager.login_view = "auth.login"

    @login_manager.user_loader
    def load_user(user_id):
        return get_user_by_id(user_id)

    app.register_blueprint(auth_bp)

    return app
```

### 3. Implement authentication

Assume the `users` table contains `id`, `username`, and `password_hash`.

```python
# auth.py
import logging

import redis
from flask import Blueprint, flash, redirect, render_template, request, url_for
from flask_login import UserMixin, current_user, login_required, login_user, logout_user
from werkzeug.security import check_password_hash, generate_password_hash

auth_bp = Blueprint("auth", __name__)

redis_client = redis.Redis(
    host="localhost",
    port=6379,
    db=0,
    decode_responses=True,
)

MAX_LENGTH = 50
MAX_ATTEMPTS = 5
LOCKOUT_SECONDS = 60 * 60


class User(UserMixin):
    def __init__(self, user_id, username, password_hash):
        self.id = user_id
        self.username = username
        self.password_hash = password_hash


def hash_password(password):
    return generate_password_hash(password)


def validate_login(user, password):
    return user is not None and check_password_hash(user.password_hash, password)


def is_locked_out(username):
    return redis_client.exists(f"lockout:{username}") == 1


def record_failed_attempt(username):
    attempt_key = f"attempt:{username}"
    attempts = redis_client.incr(attempt_key)

    # Ensure the attempt counter expires after one hour.
    redis_client.expire(attempt_key, LOCKOUT_SECONDS)

    if attempts >= MAX_ATTEMPTS:
        redis_client.setex(
            f"lockout:{username}",
            LOCKOUT_SECONDS,
            "1",
        )


def clear_failed_attempts(username):
    redis_client.delete(
        f"attempt:{username}",
        f"lockout:{username}",
    )


@auth_bp.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        if not username or not password:
            flash("Username and password are required.", "error")
            return render_template("login.html"), 400

        if len(username) > MAX_LENGTH or len(password) > MAX_LENGTH:
            flash("Username and password must be 50 characters or fewer.", "error")
            return render_template("login.html"), 400

        if is_locked_out(username):
            flash("Too many failed attempts. Try again later.", "error")
            return render_template("login.html"), 429

        user = get_user_by_username(username)

        if not validate_login(user, password):
            record_failed_attempt(username)
            logging.warning("Failed login attempt for username=%s", username)
            flash("Invalid username or password.", "error")
            return render_template("login.html"), 401

        clear_failed_attempts(username)
        login_user(user)
        logging.info("Successful login for username=%s", username)

        return redirect(url_for("dashboard"))

    return render_template("login.html")


@auth_bp.route("/logout", methods=["POST"])
@login_required
def logout():
    username = current_user.username
    logout_user()
    logging.info("User logged out: %s", username)
    return redirect(url_for("auth.login"))
```

Replace `get_user_by_id()` and `get_user_by_username()` with your database queries.

### 4. Protect routes

```python
from flask_login import login_required


@app.route("/dashboard")
@login_required
def dashboard():
    return render_template("dashboard.html")
```

Use HTTPS, secure `HttpOnly` cookies, CSRF protection for forms, and keep `SECRET_KEY` in an environment variable. Passwords should only be stored as hashes, never plaintext.

Yes. Use a small in-memory cache with a TTL—no dependencies required. For data that should survive refreshes, optionally persist it in `localStorage`.

```js
const cache = new Map();
const CACHE_TTL = 60 * 60 * 1000; // 1 hour

async function fetchWeather(city) {
  const key = city.trim().toLowerCase();
  const cached = cache.get(key);

  if (cached && cached.expires > Date.now()) {
    return cached.data;
  }

  const response = await fetch(
    `/api/weather?city=${encodeURIComponent(city)}`
  );

  if (!response.ok) {
    throw new Error(`HTTP error: ${response.status}`);
  }

  const data = await response.json();

  cache.set(key, {
    data,
    expires: Date.now() + CACHE_TTL
  });

  return data;
}
```

Use a longer TTL, such as 30–60 minutes, to reduce calls against the daily quota. Your autocomplete can retain its existing lightweight LRU cache: maximum 100 entries with a 5-minute TTL. For persistent recent searches, keep the existing `localStorage` cache limited to the last three cities.
